CREATE EXTENSION IF NOT EXISTS postgis;
CREATE TABLE IF NOT EXISTS vets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, specialization TEXT, region TEXT);
CREATE TABLE IF NOT EXISTS cases (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), reported_by TEXT, species TEXT NOT NULL, herd_size INT, symptoms TEXT NOT NULL, affected_count INT, mortality_count INT DEFAULT 0, vaccination_status TEXT, village TEXT, district TEXT, latitude FLOAT, longitude FLOAT, season TEXT, status TEXT DEFAULT 'new', priority TEXT DEFAULT 'normal', assigned_vet_id UUID REFERENCES vets(id), created_at TIMESTAMP DEFAULT now());
CREATE TABLE IF NOT EXISTS historical_cases (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), species TEXT, symptoms TEXT, season TEXT, region TEXT, confirmed_diagnosis TEXT, treatment_summary TEXT, outcome TEXT);
CREATE TABLE IF NOT EXISTS diagnoses (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), case_id UUID REFERENCES cases(id), vet_id UUID REFERENCES vets(id), ai_suggested_diagnosis TEXT, confirmed_diagnosis TEXT, notes TEXT, created_at TIMESTAMP DEFAULT now());
CREATE TABLE IF NOT EXISTS treatment_steps (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), case_id UUID REFERENCES cases(id), step_number INT NOT NULL, step_name TEXT NOT NULL, notes TEXT, proof_url TEXT, completed_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS lab_requests (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), case_id UUID REFERENCES cases(id), requested_at TIMESTAMP DEFAULT now(), status TEXT DEFAULT 'requested', report_url TEXT);
